import { execSync } from "node:child_process";
import { createHash } from "node:crypto";
import { constants } from "node:fs";
import { open } from "node:fs/promises";

const file = process.argv[2];
const openFiles = () => Number(execSync(`lsof -p ${process.pid} | wc -l`).toString().trim());

const hashOnce = async (autoClose: boolean) => {
	const handle = await open(file, constants.O_RDONLY | constants.O_NOFOLLOW);
	try {
		const hash = createHash("sha256");
		for await (const chunk of handle.createReadStream({ start: 0, autoClose })) hash.update(chunk);
		return hash.digest("hex");
	} finally {
		await handle.close();
	}
};

for (const autoClose of [false, true]) {
	const before = openFiles();
	for (let i = 0; i < 50; i++) await hashOnce(autoClose);
	console.log(JSON.stringify({ runtime: `bun ${Bun.version}`, autoClose, calls: 50, before, after: openFiles() }));
}

